#!/bin/sh
# Build a timestamped markdown monitoring report from environment variables.
# Expected env (set by the workflow):
#   REPORT_PATH, REPO, BRANCH, SHA, RUN_URL, TRIGGER, GENERATED_AT_UTC
#   CHECK_LINES — multiline "name|status|severity|evidence" records
#   SUMMARY_NOTE — optional free text (already redacted)
set -eu

REPORT_PATH="${REPORT_PATH:?REPORT_PATH is required}"
REPO="${REPO:-unknown}"
BRANCH="${BRANCH:-unknown}"
SHA="${SHA:-unknown}"
RUN_URL="${RUN_URL:-}"
TRIGGER="${TRIGGER:-manual}"
GENERATED_AT_UTC="${GENERATED_AT_UTC:-$(date -u +%Y-%m-%dT%H:%M:%SZ)}"
SUMMARY_NOTE="${SUMMARY_NOTE:-}"

mkdir -p "$(dirname "$REPORT_PATH")"

{
  echo "# Attendance SaaS — monitoring report"
  echo
  echo "| Field | Value |"
  echo "| --- | --- |"
  echo "| Repository | \`${REPO}\` |"
  echo "| Branch | \`${BRANCH}\` |"
  echo "| Commit | \`${SHA}\` |"
  echo "| Generated (UTC) | \`${GENERATED_AT_UTC}\` |"
  echo "| Trigger | \`${TRIGGER}\` |"
  if [ -n "$RUN_URL" ]; then
    echo "| Workflow run | [Open run](${RUN_URL}) |"
  fi
  echo
  echo "## Check results"
  echo
  echo "| Check | Status | Severity | Evidence |"
  echo "| --- | --- | --- | --- |"

  if [ -n "${CHECK_LINES:-}" ]; then
    printf '%s\n' "$CHECK_LINES" | while IFS= read -r line; do
      [ -z "$line" ] && continue
      name=$(printf '%s' "$line" | cut -d'|' -f1)
      status=$(printf '%s' "$line" | cut -d'|' -f2)
      severity=$(printf '%s' "$line" | cut -d'|' -f3)
      evidence=$(printf '%s' "$line" | cut -d'|' -f4-)
      echo "| ${name} | **${status}** | ${severity} | ${evidence} |"
    done
  else
    echo "| _(none)_ | NOT TESTED | info | No checks recorded |"
  fi

  echo
  echo "## Status legend"
  echo
  echo "- **PASS** — check ran and succeeded"
  echo "- **FAIL** — check ran and failed (confirmed)"
  echo "- **PARTIAL** — incomplete coverage or non-blocking advisories"
  echo "- **BLOCKED** — required infrastructure/secret/URL missing; not a confirmed app failure"
  echo "- **NOT TESTED** — check not executed in this run"
  echo
  echo "## Notes"
  echo
  if [ -n "$SUMMARY_NOTE" ]; then
    printf '%s\n' "$SUMMARY_NOTE"
  else
    echo "No additional notes."
  fi
  echo
  echo "## Remediation"
  echo
  echo "This monitor is **read-only**. It does not modify code, databases, or infrastructure."
  echo "Do not treat this email or report as approval to apply fixes."
  echo "Remediation requires your **explicit** approval of a specific finding."
  echo
  echo "---"
  echo
  echo "_Report generated by \`.github/workflows/monitor.yml\`._"
} > "$REPORT_PATH"

echo "Wrote ${REPORT_PATH}"
